require_once '../../config/sesion.php'; verificarAdmin(); require_once '../../controllers/LearningController.php'; require_once '../../includes/learning_helpers.php'; $learning=new LearningController(); $rows=$learning->seguimientoAdmin(); $filtro=$_GET['estado']??''; if($filtro) $rows=array_values(array_filter($rows,fn($r)=>$r['estado']===$filtro));
