<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seguimiento - Learning Lab</title><link rel="stylesheet" href="../../assets/css/admin.css"></head><body><?php include '../includes/sidebar.php'; ?><div class="admin-main"><?php include '../includes/navbar.php'; ?><section class="admin-content learning-admin-page"><div class="gestion-header"><div><span class="learning-admin-kicker">Seguimiento</span><h1>Progreso de usuarios</h1><p class="dashboard-subtitle">Controla avance, fechas límite, estado y resultados de evaluación.</p></div></div><form method="GET" class="filtros-admin learning-filter"><div><label>Estado</label><select name="estado"><option value="">Todos</option><?php foreach(['pendiente','en_progreso','completada','vencida'] as $e): ?><option value="<?php echo $e; ?>" <?php echo $filtro===$e?'selected':''; ?>><?php echo learningEstadoTexto($e); ?></option><?php endforeach; ?></select></div><div class="filtros-botones"><button class="btn-filtrar">Filtrar</button><a class="btn-limpiar" href="seguimiento.php">Limpiar</a></div></form><div class="admin-table-wrapper"><table class="admin-table"><thead><tr><th>Usuario</th><th>Curso / capacitación</th><th>Fecha límite</th><th>Progreso</th><th>Mejor nota</th><th>Estado</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="tabla-vacia">No hay resultados para este filtro.</td></tr><?php else: foreach($rows as $r): ?><tr><td><strong><?php echo learningH($r['nombre']); ?></strong><small class="learning-table-sub"><?php echo learningH($r['email']); ?></small></td><td><strong><?php echo learningH($r['curso']); ?></strong><small class="learning-table-sub"><?php echo learningH($r['capacitacion']); ?></small></td><td><?php echo learningH($r['fecha_limite']); ?></td><td><div class="learning-progress-inline"><span><i style="width:<?php echo min(100,(float)$r['porcentaje']); ?>%"></i></span><b><?php echo (float)$r['porcentaje']; ?>%</b></div></td><td><?php echo $r['mejor_nota']!==null?round((float)$r['mejor_nota'],1).'%':'—'; ?></td><td><span class="learning-badge <?php echo learningEstadoClase($r['estado']); ?>"><?php echo learningEstadoTexto($r['estado']); ?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></section></div></body></html>
